codeExamples.code:
// Allocate 16 bytes of binary memory
let buffer = new ArrayBuffer(16);

console.log(buffer.byteLength);  // 16

// Create a view to access the bytes
let view = new Uint8Array(buffer);
console.log(view);  // Uint8Array(16) [0, 0, 0, ..., 0]

// Write bytes
view[0] = 72;   // 'H'
view[1] = 105;  // 'i'

console.log(view.slice(0, 2));  // [72, 105]

// Float32Array for physics simulation
let positions = new Float32Array(6);
positions[0] = 1.5;  // x1
positions[1] = 2.0;  // y1
positions[2] = 3.5;  // x2
positions[3] = 4.0;  // y2

// Array-like operations
let doubled = new Float64Array(positions.map(x => x * 2));
console.log(doubled);  // Float64Array [3, 4, 7, 8, 0, 0]

// From regular array
let bytes = new Uint8Array([72, 101, 108, 108, 111]);
let text = new TextDecoder().decode(bytes);
console.log(text);  // "Hello"

let buffer = new ArrayBuffer(8);
let view = new DataView(buffer);

// Write a 32-bit integer at byte 0
view.setInt32(0, 1000, false);  // big-endian

// Write a 16-bit integer at byte 4
view.setInt16(4, 256, true);    // little-endian

// Read them back
console.log(view.getInt32(0, false));  // 1000
console.log(view.getInt16(4, true));   // 256

// Different byte orders for the same data
view.setInt32(0, 256, false);  // big-endian: [0,0,1,0]
view.setInt32(0, 256, true);   // little-endian: [0,1,0,0]

let encoder = new TextEncoder();
let decoder = new TextDecoder();

// Encode string to bytes
let encoded = encoder.encode("Hello, 世界!");
console.log(encoded);     // Uint8Array(13) [72, 101, ...]
console.log(encoded.length);  // 13 bytes (not 9 chars!)

// Decode bytes to string
let decoded = decoder.decode(encoded);
console.log(decoded);     // "Hello, 世界!"

// Different encodings
let utf16decoder = new TextDecoder("utf-16");
let utf16bytes = new Uint8Array([255, 254, 72, 0, 105, 0]);
console.log(utf16decoder.decode(utf16bytes));  // "Hi"

